{
  "judgments": [
    {
      "proposal_id": "P0000",
      "quotes": [
        "Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:\n\n(1) A streetcar crossing, or railroad tracks used exclusively for industrial switching purposes, within a business district, as defined in § 390.5 of this chapter."
      ],
      "rationale": "Paragraph (a) establishes the baseline requirement to stop before crossing railroad tracks at grade, explicitly qualifying this duty with the caveat 'Except as provided in paragraph (b) of this section'. Paragraph (b)(1) provides that a stop need not be made at streetcar crossings or industrial switching tracks in a business district. Setting qualifies to ['C0000'] and relation to 'exception' correctly transforms the prose caveat into an explicit qualification edge without altering any substantive terms.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0001",
      "quotes": [
        "Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:",
        "(2) A railroad grade crossing when a police officer or crossing flagman directs traffic to proceed."
      ],
      "rationale": "Paragraph (a) establishes the mandatory stopping duty subject to the exceptions in paragraph (b). Paragraph (b)(2) specifies that a stop need not be made when a police officer or crossing flagman directs traffic to proceed. Designating C0010 as an exception qualifying baseline duty C0000 accurately operationalizes the textual caveat in the regulation.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0002",
      "quotes": [
        "Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:",
        "(3) A railroad grade crossing controlled by a functioning highway traffic signal transmitting a green indication which, under local law, permits the commercial motor vehicle to proceed across the railroad tracks without slowing or stopping."
      ],
      "rationale": "Paragraph (a) explicitly subordinates the grade crossing stop requirement to paragraph (b), where subparagraph (b)(3) exempts crossings controlled by a functioning green highway traffic signal permitting passage without stopping under local law. Linking C0011 to baseline C0000 with an exception relation faithfully represents this qualification structure.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0003",
      "quotes": [
        "Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:",
        "(4) An abandoned railroad grade crossing which is marked with a sign indicating that the rail line is abandoned."
      ],
      "rationale": "Paragraph (a) establishes the stopping requirement except as provided in paragraph (b). Paragraph (b)(4) relieves drivers from making a stop at an abandoned railroad grade crossing marked with an abandoned rail line sign. Adding an explicit exception link from C0012 to C0000 correctly implements the textual exception.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0004",
      "quotes": [
        "Except as provided in paragraph (b) of this section, the driver of a commercial motor vehicle specified in paragraphs (a) (1) through (6) of this section shall not cross a railroad track or tracks at grade unless he/she first: Stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks",
        "(b) A stop need not be made at:",
        "(5) An industrial or spur line railroad grade crossing marked with a sign reading “Exempt.”"
      ],
      "rationale": "The mandatory stopping obligation under paragraph (a) is prefaced by 'Except as provided in paragraph (b) of this section', and paragraph (b)(5) explicitly provides that a stop need not be made at industrial or spur line crossings marked 'Exempt'. Linking C0013 as an exception qualifying C0000 correctly represents this relationship.",
      "verdict": "supported"
    }
  ]
}
